+// Insertion sort for small runs.
+static void insertion_sort(uint32_t* a, size_t n) {
+    for (size_t i = 1; i < n; ++i) {
+        uint32_t v = a[i];
+        size_t j = i;
+        while (j > 0 && a[j - 1] > v) {
+            a[j] = a[j - 1];
+            --j;
+        }
+        a[j] = v;
+    }
+}
